defmodule Bitblocks.Repo.Migrations.AddWebhookToProjections do
  use Ecto.Migration

  # #29 step 4, follow by webhook.
  #
  # webhook_url    — where new matches (and reorg rewinds) are POSTed; null
  #                  means hydrate-only.
  # webhook_secret — HMAC-SHA256 key for the x-bitblocks-signature header.
  #                  Generated by Bitblocks, shown once at registration; stored
  #                  in the clear because signing needs it. Per projection
  #                  until tenant keys exist (step 5).
  def change do
    alter table(:projections) do
      add(:webhook_url, :string)
      add(:webhook_secret, :string)
    end
  end
end
